+const isTableRow = (line: string): boolean => /^\|.*\|\s*$/.test(line);
+
+const isTableDelimiter = (line: string): boolean =>
+  /^\|\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|\s*$/.test(line);
+
+const compactTableRow = (line: string): string =>
+  `|${line
+    .trim()
+    .slice(1, -1)
+    .split("|")
+    .map((cell) => cell.trim())
+    .join("|")}|`;
+
+/** Normalize pipe tables to Markdownlint's compact style without touching fenced code. */
+export const compactMarkdownTables = (markdown: string): string => {
+  const lines = markdown.split("\n");
+  const output: string[] = [];
+  let inFence = false;
+
+  for (let index = 0; index < lines.length; index++) {
+    const line = lines[index];
+    if (line.trimStart().startsWith("```")) inFence = !inFence;
+
+    if (
+      !inFence &&
+      isTableRow(line) &&
+      isTableDelimiter(lines[index + 1] ?? "")
+    ) {
+      output.push(compactTableRow(line));
+      output.push(compactTableRow(lines[++index]));
+      while (isTableRow(lines[index + 1] ?? "")) output.push(compactTableRow(lines[++index]));
+      continue;
+    }
+
+    output.push(line);
+  }
+
+  return output.join("\n");
+};
+
+/** Verify that a translated guide retained the structural elements the writer depends on. */
+export const preservesMarkdownStructure = (source: string, translated: string): boolean => {
+  const count = (value: string, pattern: RegExp): number => value.match(pattern)?.length ?? 0;
+  return (
+    count(source, /^#{1,6}\s/mg) === count(translated, /^#{1,6}\s/mg) &&
+    count(source, /^```/gm) === count(translated, /^```/gm) &&
+    count(source, /^\|.*\|\s*$/gm) === count(translated, /^\|.*\|\s*$/gm)
+  );
+};
